contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint oldPropId, uint newPropId, uint weight) public {
        // Bound inputs to realistic ranges
        oldPropId = bound(oldPropId, 1, 100);
        newPropId = bound(newPropId, 1, 100);
        vm.assume(oldPropId != newPropId);
        weight = bound(weight, 1, 1000);

        // First, we need the vault to have some totalWeight
        // We'll simulate by setting up state via the contract's public functions
        // The test needs the vault to return non-zero totalWeight
        // Since we cannot set vault directly, we can assume it's already deployed
        // For fuzzing, we can use vm.assume to restrict to cases where cancelProposal would succeed
        // We'll first create proposals to have some state

        // Create an old proposal that will be finalising
        // We need to call voteProposal to make it finalising (hasQuorum + hasMajority)
        // But we don't have direct control over vault weight - assume it's set up

        // The general rule: after cancelProposal on a valid pair, 
        // the old proposal's votes become 0

        // Drive the contract to create both proposals
        c.newAddressProposal(address(0x123), "TEST");
        c.newAddressProposal(address(0x456), "TEST");

        // Try to make oldProposalId finalising by voting
        // (this requires vault weight > 0, which we must assume)
        // Use try/catch since it may revert
        try c.voteProposal(oldPropId) {
            // If vote succeeded, try cancelProposal
            try c.cancelProposal(oldPropId, newPropId) {
                // Assertion: the old proposal's votes are reset to 0
                assertTrue(c.mapPID_votes(oldPropId) == 0);
