pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _vader, address _usdv, address _vault, address recipient, uint256 amount, uint256 oldProposalID, uint256 newProposalID) public {
        // Bound inputs to reasonable values
        vm.assume(_vader != address(0));
        vm.assume(_usdv != address(0));
        vm.assume(_vault != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(oldProposalID > 0 && oldProposalID <= 10);
        vm.assume(newProposalID > 0 && newProposalID <= 10);
        vm.assume(oldProposalID != newProposalID);

        // Initialize contract
        c.init(_vader, _usdv, _vault);
        address vaderBefore = c.VADER();

        // Create proposals to enable cancelProposal
        // First create two proposals of the same type (GRANT) so cancelProposal can work
        c.newGrantProposal(recipient, amount);
        c.newGrantProposal(recipient, amount);

        // Try to cancel oldProposalID with newProposalID, may revert if conditions not met
        (bool ok,) = address(c).call(abi.encodeWithSignature("cancelProposal(uint256,uint256)", oldProposalID, newProposalID));

        // Regardless of revert, VADER must never change
        address vaderAfter = c.VADER();
        assertTrue(vaderBefore == vaderAfter, "VADER should not change after cancelProposal");
