        vm.assume(_usdv != address(0));
        vm.assume(_vault != address(0));
        vm.assume(proposalID1 != proposalID2);
        vm.assume(proposalID1 > 0 && proposalID1 <= type(uint256).max);
        vm.assume(proposalID2 > 0 && proposalID2 <= type(uint256).max);

        // Initialize contract
        c.init(_vader, _usdv, _vault);

        // Create two proposals to satisfy cancelProposal conditions
        c.newAddressProposal(_vader, "DAO");
