pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address vader = address(0x1234);
    address usdv = address(0x5678);
    address vault = address(0x9abc);

    function setUp() public { 
        c = new C(); 
        c.init(vader, usdv, vault);
    }

    function testFuzz_property(uint256 p1, uint256 p2) public {
        // First create two proposals of the same type (e.g., "GRANT")
        // so cancelProposal can be called with different IDs
        vm.assume(p1 != p2);

        // Create an old proposal and a new proposal
        c.newGrantProposal(address(0x1111), 100);
        c.newGrantProposal(address(0x2222), 200);

        uint256 oldProposalID = 1;
        uint256 newProposalID = 2;

        // We need to make the old proposal finalizing and the new one have minority
        // First vote on old proposal to pass quorum and majority
        c.voteProposal(oldProposalID);

        // Now old proposal is finalising, we can try to cancel it
        // with a new proposal that has minority (zero votes)

        // Call cancelProposal - this should succeed
        vm.prank(address(0xdead));
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("cancelProposal(uint256,uint256)", oldProposalID, newProposalID)
        );

        if (success) {
            // After successful cancelProposal, VADER should still be the original _vader
            assertTrue(c.VADER() == vader, "VADER should equal _vader from init after cancelProposal");
        } else {
            // If revert, still check VADER is unchanged
            assertTrue(c.VADER() == vader, "VADER should equal _vader from init even on revert");
        }
    }
}

