import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address refVader;
    address refUsdv;
    address refVault;

    function setUp() public { 
        c = new C(); 
        refVader = makeAddr("vader");
        refUsdv = makeAddr("usdv");
        refVault = makeAddr("vault");
        c.init(refVader, refUsdv, refVault);
    }

    function testFuzz_property(uint256 newProposalId, uint256 oldProposalId) public {
        // Ensure proposal IDs are distinct and non-zero
        vm.assume(newProposalId != oldProposalId);
        vm.assume(newProposalId > 0 && oldProposalId > 0);

        // Create proposals of the same type to satisfy cancelProposal requirements
        // We'll use 'DAO' type since it's one of the recognized types
        c.newAddressProposal(address(0x1), "DAO"); // proposal 1
        c.newAddressProposal(address(0x2), "DAO"); // proposal 2

        // cast votes to set mapPID_votes for both proposals
        // (needed for cancelProposal checks)
        vm.prank(address(0xDEAD));
        c.voteProposal(1);
        vm.prank(address(0xBEEF));
        c.voteProposal(2);

        // Record VADER before cancel
        address vaderBefore = c.VADER();

        // Call cancelProposal — may revert due to various conditions, but that's fine
        // We'll use a try/catch to handle reversion
        try c.cancelProposal(1, 2) {
            address vaderAfter = c.VADER();
            assertTrue(vaderAfter == refVader, "VADER changed after cancelProposal");
        } catch {
            // If it reverts, the state is unchanged
            address vaderAfter = c.VADER();
            assertTrue(vaderAfter == refVader, "VADER changed even on revert");
        }
    }
}

